Font = {
    init: async function(app, container, observable) {
        app = app || session.app;
        container = container || $(".component[name=Font]");
        if(!observable) { return; }
        if(observable) {
            $("[name=fontSizeSlider]", container).kendoSlider({ 
                min: 0, 
                max: 20, 
                smallStep: 1, 
                largeStep: 2, 
                value: parseFloat(observable.get("font.size").replaceAll("px", "")),
                change: function(e) {
                    e.preventDefault();
                    observable.set("font.size", this.value() + "px");
                    $("[name=fontSizePreview]", container).css("font-size",  observable.get("font.size"));
                }
            });
            $("[name=fontSizePreview]", container).css("font-size", observable.get("font.size"));
        }

    }
}
